sp_widget.client_script:
function addAttachmentRow() {
  const template = document.getElementById('attachmentTemplate');
  const clone = template.content.cloneNode(true);

  // 文件选择监听
  const fileInput = clone.querySelector('.file-input');
  const fileName = clone.querySelector('.file-name');

  fileInput.addEventListener('change', function(e) {
    fileName.textContent = e.target.files[0]?.name || '';
  });

  document.getElementById('attachmentsContainer').appendChild(clone);
}

// 初始添加一行
addAttachmentRow();
